<script setup lang="ts">
import { ref, watch } from 'vue'
import { api } from '@/lib/api'
import { useGovernanceStore } from '@/stores/governance'
import type { PolicyDecision } from '@/types'
import PageHeader from '@/components/common/PageHeader.vue'
import EmptyState from '@/components/common/EmptyState.vue'
import { Button } from '@/components/ui/button'
const governance = useGovernanceStore()
const tool = ref(''); const operation = ref(''); const target = ref(''); const version = ref('')
const loading = ref(false); const error = ref(''); const result = ref<PolicyDecision | null>(null)
let generation = 0
watch(() => governance.activeProjectId, () => { generation++; result.value = null; error.value = ''; version.value = ''; loading.value = false })
async function simulate() { const id = governance.activeProjectId; if (!id || !governance.policy) return; const request = ++generation; loading.value = true; error.value = ''; result.value = null; try { const response = await api.simulate(id, { action: { tool: tool.value, operation: operation.value, target: target.value }, ...(version.value ? { version: Number(version.value) } : {}) }); if (generation === request) result.value = response } catch (e) { if (generation === request) error.value = e instanceof Error ? e.message : '模拟失败' } finally { if (generation === request) loading.value = false } }
</script>
<template><div class="page"><PageHeader title="动作模拟" description="使用已发布策略进行假设评估；不会执行或授权动作。"/><div class="mb-4 rounded-md border border-border bg-surface p-3 text-xs text-muted-foreground">模拟使用引擎默认值，结果不等同于运行时 log-only 记录器，也不是执行许可。</div><EmptyState v-if="!governance.activeProject" title="请选择项目" description="请先在侧栏选择项目。"/><EmptyState v-else-if="!governance.policy" title="尚无已发布策略" description="请先提交并批准提案，发布后才能模拟。"/><div v-else class="grid gap-4 lg:grid-cols-2"><section class="panel"><div class="panel-header"><h2 class="panel-title">输入动作</h2></div><form class="space-y-4 p-4" @submit.prevent="simulate"><label class="field"><span class="field-label">工具 tool</span><input v-model="tool" required class="h-9 rounded-md border border-input bg-background px-3 text-sm" /></label><label class="field"><span class="field-label">操作 operation</span><input v-model="operation" required class="h-9 rounded-md border border-input bg-background px-3 text-sm" /></label><label class="field"><span class="field-label">目标 target</span><input v-model="target" required class="h-9 rounded-md border border-input bg-background px-3 text-sm" /></label><label class="field"><span class="field-label">已发布版本</span><select v-model="version" class="h-9 rounded-md border border-input bg-background px-3 text-sm"><option value="">当前版本</option><option v-for="item in governance.versions" :key="item.version" :value="String(item.version)">版本 {{ item.version }}</option></select></label><p v-if="error" class="text-xs text-destructive" role="alert">{{ error }}</p><Button type="submit" :disabled="loading">{{ loading ? '模拟中…' : '模拟裁决' }}</Button></form></section><section class="panel"><div class="panel-header"><h2 class="panel-title">假设结果</h2></div><div v-if="result" class="space-y-3 p-4 text-sm"><p>裁决：<strong>{{ result.verdict }}</strong></p><p>决策类型：{{ result.decision }}</p><p>命中规则：{{ result.matched_rule_ids.join(', ') || '无' }}</p><p v-if="result.error" class="text-destructive">{{ result.error }}</p><ul class="space-y-2"><li v-for="rule in result.matched_rules" :key="rule.id" class="rounded-md border border-border p-3 text-xs">{{ rule.id }} · {{ rule.dimension }} · level {{ rule.level }} · {{ rule.policy_class }} / {{ rule.enforcement }} / {{ rule.on_hit }}</li></ul></div><p v-else class="p-6 text-center text-xs text-muted-foreground">提交动作后显示假设裁决。</p></section></div></div></template>
